class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, privately accounted daily equity strategies."""

    AAPL_RED_DAYS_REQUIRED = 3

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_closes = RollingWindow[float](101)
        self.previous_spy_above_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi_previous_close = None
        self.aapl_rsi_change_count = 0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_initial_gains = 0.0
        self.aapl_initial_losses = 0.0

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data):
        bars = {}
        complete_slice = True
        for ticker, symbol in self.symbols.items():
            if not data.bars.contains_key(symbol):
                complete_slice = False
                continue
            bars[ticker] = data.bars[symbol]

        spy_crossed_above = False
        spy_crossed_below = False
        if "SPY" in bars:
            spy_close = float(bars["SPY"].close)
            self.spy_closes.add(spy_close)
            if self.spy_closes.is_ready:
                spy_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
                spy_above_sma = spy_close > spy_sma
                if self.previous_spy_above_sma is not None:
                    spy_crossed_above = (
                        not self.previous_spy_above_sma and spy_above_sma
                    )
                    spy_crossed_below = (
                        self.previous_spy_above_sma and not spy_above_sma
                    )
                self.previous_spy_above_sma = spy_above_sma

        aapl_rsi = None
        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            aapl_rsi = self._update_aapl_rsi(aapl_close)

        if not complete_slice:
            return

        # Strategy A: sells are evaluated before buys.
        if self.spy_lot > 0:
            if spy_crossed_below:
                self.market_order(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        elif self.spy_closes.is_ready and spy_crossed_above:
            allocation = float(self.portfolio.total_portfolio_value) * 0.40
            quantity = int(allocation // float(bars["SPY"].close))
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        # Strategy B: sells are evaluated before buys.
        if self.aapl_lot > 0:
            if aapl_rsi is not None and aapl_rsi > 60.0:
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif (
            aapl_rsi is not None
            and self.aapl_red_streak >= self.AAPL_RED_DAYS_REQUIRED
            and float(self.portfolio.cash_book["USD"].amount) >= 20_000.0
        ):
            quantity = int(20_000.0 // float(bars["AAPL"].close))
            if quantity > 0:
                self.market_order(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

    def _update_aapl_rsi(self, close):
        if self.aapl_rsi_previous_close is None:
            self.aapl_rsi_previous_close = close
            return None

        change = close - self.aapl_rsi_previous_close
        self.aapl_rsi_previous_close = close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.aapl_rsi_change_count < 14:
            self.aapl_initial_gains += gain
            self.aapl_initial_losses += loss
            self.aapl_rsi_change_count += 1
            if self.aapl_rsi_change_count < 14:
                return None
            self.aapl_average_gain = self.aapl_initial_gains / 14.0
            self.aapl_average_loss = self.aapl_initial_losses / 14.0
        else:
            self.aapl_average_gain = (self.aapl_average_gain * 13.0 + gain) / 14.0
            self.aapl_average_loss = (self.aapl_average_loss * 13.0 + loss) / 14.0

        if self.aapl_average_loss == 0.0:
            return 100.0 if self.aapl_average_gain > 0.0 else 50.0
        relative_strength = self.aapl_average_gain / self.aapl_average_loss
        return 100.0 - 100.0 / (1.0 + relative_strength)

