class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    """Two independent, close-of-day strategies with privately tracked lots."""

    RED_DAYS_REQUIRED = 3

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=2)
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        # A day is usable only when all five subscriptions supplied a trade bar.
        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                return
            bars[ticker] = data.Bars[symbol]

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)
        self.aapl_rsi.Update(data.Time, aapl_close)

        if len(self.aapl_closes) == 2:
            if self.aapl_closes[-1] < self.aapl_closes[-2]:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Strategy A: sell before buy.
        if len(self.spy_closes) == 101:
            yesterday_close = self.spy_closes[-2]
            today_close = self.spy_closes[-1]
            yesterday_sma = sum(list(self.spy_closes)[:100]) / 100.0
            today_sma = sum(list(self.spy_closes)[1:]) / 100.0

            crosses_below = yesterday_close >= yesterday_sma and today_close < today_sma
            crosses_above = yesterday_close <= yesterday_sma and today_close > today_sma

            if self.spy_lot > 0 and crosses_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
            elif self.spy_lot == 0 and crosses_above:
                quantity = floor((0.40 * float(self.Portfolio.TotalPortfolioValue)) / today_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.spy_lot = quantity

        # Strategy B: sell before buy.
        if self.aapl_lot > 0 and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0
        elif self.aapl_lot == 0 and self.aapl_red_streak >= self.RED_DAYS_REQUIRED:
            cash_required = 20_000.0
            if float(self.Portfolio.Cash) >= cash_required:
                quantity = floor(cash_required / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

