class IndependentSpyAndAaplStrategies(QCAlgorithm):
    """Two independent, privately accounted daily equity strategies."""

    RED_DAYS_REQUIRED = 3

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            security = self.AddEquity(ticker, Resolution.Daily)
            security.SetDataNormalizationMode(DataNormalizationMode.Adjusted)
            self.symbols[ticker] = security.Symbol

        self.spy_closes = deque(maxlen=100)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def OnData(self, data: Slice):
        has_every_bar = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )
        spy_bar = (
            data.Bars[self.symbols["SPY"]]
            if data.Bars.ContainsKey(self.symbols["SPY"])
            else None
        )
        aapl_bar = (
            data.Bars[self.symbols["AAPL"]]
            if data.Bars.ContainsKey(self.symbols["AAPL"])
            else None
        )

        spy_sma = None
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))
            if len(self.spy_closes) == 100:
                spy_sma = sum(self.spy_closes) / 100.0

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_rules_ready = (
            spy_sma is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close is not None
            and self.previous_aapl_close is not None
            and self.aapl_rsi.IsReady
        )

        if has_every_bar and all_rules_ready:
            # Sells are evaluated before buys. Each strategy can touch only its lot.
            if self.strategy_a_shares > 0 and not self.strategy_a_pending:
                crossed_below = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_bar.Close < spy_sma
                )
                if crossed_below:
                    self.strategy_a_pending = True
                    self.MarketOrder(
                        self.symbols["SPY"],
                        -self.strategy_a_shares,
                        tag="strategy-a-sell",
                    )

            if self.strategy_b_shares > 0 and not self.strategy_b_pending:
                if self.aapl_rsi.Current.Value > 60:
                    self.strategy_b_pending = True
                    self.MarketOrder(
                        self.symbols["AAPL"],
                        -self.strategy_b_shares,
                        tag="strategy-b-sell",
                    )

            if self.strategy_a_shares == 0 and not self.strategy_a_pending:
                crossed_above = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_bar.Close > spy_sma
                )
                if crossed_above:
                    quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                    if quantity > 0:
                        self.strategy_a_pending = True
                        self.MarketOrder(
                            self.symbols["SPY"], quantity, tag="strategy-a-buy"
                        )

            if self.strategy_b_shares == 0 and not self.strategy_b_pending:
                if self.aapl_red_streak >= self.RED_DAYS_REQUIRED:
                    if self.Portfolio.Cash >= 20_000:
                        quantity = floor(20_000 / float(aapl_bar.Close))
                        if quantity > 0:
                            self.strategy_b_pending = True
                            self.MarketOrder(
                                self.symbols["AAPL"],
                                quantity,
                                tag="strategy-b-buy",
                            )

        if spy_bar is not None:
            self.previous_spy_close = float(spy_bar.Close)
            self.previous_spy_sma = spy_sma
        if aapl_bar is not None:
            self.previous_aapl_close = float(aapl_bar.Close)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                order = self.Transactions.GetOrderById(order_event.OrderId)
                if order is not None and order.Tag.startswith("strategy-a-"):
                    self.strategy_a_pending = False
                elif order is not None and order.Tag.startswith("strategy-b-"):
                    self.strategy_b_pending = False
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Tag.startswith("strategy-a-"):
            self.strategy_a_shares += int(order_event.FillQuantity)
            if order_event.Status == OrderStatus.Filled:
                self.strategy_a_pending = False
        elif order.Tag.startswith("strategy-b-"):
            self.strategy_b_shares += int(order_event.FillQuantity)
            if order_event.Status == OrderStatus.Filled:
                self.strategy_b_pending = False

