        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                return
            bars[ticker] = data.Bars[symbol]

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        self.spy_closes.Add(spy_close)
        self.spy_sma.Update(data.Time, spy_close)
        self.aapl_rsi.Update(data.Time, aapl_close)

        if self.previous_aapl_close is not None:
            if aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        self.previous_aapl_close = aapl_close

        if not (self.spy_closes.IsReady and self.spy_sma.IsReady and self.aapl_rsi.IsReady):
            return

        previous_spy_close = self.spy_closes[1]
        previous_spy_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        current_spy_sma = float(self.spy_sma.Current.Value)

        spy_crossed_below = (
            previous_spy_close >= previous_spy_sma and spy_close < current_spy_sma
        )
        spy_crossed_above = (
            previous_spy_close <= previous_spy_sma and spy_close > current_spy_sma
        )

        # Both independent slots evaluate their exit before their entry.
        if self.spy_lot > 0 and not self.spy_order_pending and spy_crossed_below:
            self.spy_order_pending = True
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot, tag="strategy-a-sell")
        elif self.spy_lot == 0 and not self.spy_order_pending and spy_crossed_above:
            quantity = int((0.40 * float(self.Portfolio.TotalPortfolioValue)) / spy_close)
            if quantity > 0:
                self.spy_order_pending = True
                self.MarketOrder(self.symbols["SPY"], quantity, tag="strategy-a-buy")

        if (
            self.aapl_lot > 0
            and not self.aapl_order_pending
            and float(self.aapl_rsi.Current.Value) > 60
        ):
            self.aapl_order_pending = True
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot, tag="strategy-b-sell")
        elif (
            self.aapl_lot == 0
            and not self.aapl_order_pending
            and self.aapl_red_streak >= self.RED_DAYS_REQUIRED
            and float(self.Portfolio.Cash) >= 20_000
        ):
            quantity = int(20_000 // aapl_close)
            if quantity > 0:
                self.aapl_order_pending = True
                self.MarketOrder(self.symbols["AAPL"], quantity, tag="strategy-b-buy")

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                order = self.Transactions.GetOrderById(order_event.OrderId)
                if order is not None and order.Tag.startswith("strategy-a-"):
                    self.spy_order_pending = False
                elif order is not None and order.Tag.startswith("strategy-b-"):
                    self.aapl_order_pending = False
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        fill_quantity = int(order_event.FillQuantity)
        if order.Tag.startswith("strategy-a-"):
            self.spy_lot += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.spy_order_pending = False
        elif order.Tag.startswith("strategy-b-"):
            self.aapl_lot += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.aapl_order_pending = False

