            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = self.spy_sma.Current.Value

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.previous_aapl_close = aapl_bar.Close

        # A day's rules are atomic across the five subscriptions.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return
        if self.IsWarmingUp or not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return
        if old_spy_close is None or old_spy_sma is None:
            return

        # Sells are evaluated before buys. Each strategy can act only on the
        # side appropriate to the state of its own private lot.
        if self.spy_lot > 0 and not self.spy_order_pending:
            crossed_below = old_spy_close >= old_spy_sma and spy_bar.Close < self.spy_sma.Current.Value
            if crossed_below:
                self.spy_order_pending = True
                self.MarketOrder(self.spy, -self.spy_lot, False, "Strategy A sell")

        if self.aapl_lot > 0 and not self.aapl_order_pending:
            if self.aapl_rsi.Current.Value > 60:
                self.aapl_order_pending = True
                self.MarketOrder(self.aapl, -self.aapl_lot, False, "Strategy B sell")

        if self.spy_lot == 0 and not self.spy_order_pending:
            crossed_above = old_spy_close <= old_spy_sma and spy_bar.Close > self.spy_sma.Current.Value
            if crossed_above:
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self.spy_order_pending = True
                    self.MarketOrder(self.spy, quantity, False, "Strategy A buy")

        if self.aapl_lot == 0 and not self.aapl_order_pending:
            if self.aapl_red_streak >= self.AAPL_RED_DAYS and self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 // aapl_bar.Close)
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.MarketOrder(self.aapl, quantity, False, "Strategy B buy")

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            if order.Tag.startswith("Strategy A"):
                self.spy_lot = max(0, self.spy_lot + int(order_event.FillQuantity))
            elif order.Tag.startswith("Strategy B"):
                self.aapl_lot = max(0, self.aapl_lot + int(order_event.FillQuantity))

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            if order.Tag.startswith("Strategy A"):
                self.spy_order_pending = False
            elif order.Tag.startswith("Strategy B"):
                self.aapl_order_pending = False

