        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = RollingWindow[float](101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        spy_bar = data.bars.get(self.symbols["SPY"])
        aapl_bar = data.bars.get(self.symbols["AAPL"])

        if spy_bar is not None:
            self.spy_closes.add(float(spy_bar.close))

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        if any(data.bars.get(symbol) is None for symbol in self.symbols.values()):
            return

        if not self.spy_closes.is_ready or not self.aapl_rsi.is_ready:
            return

        spy_close_today = self.spy_closes[0]
        spy_close_yesterday = self.spy_closes[1]
        spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(
            self.spy_closes[i] for i in range(1, 101)
        ) / 100.0

        spy_crossed_below = (
            spy_close_yesterday >= spy_sma_yesterday
            and spy_close_today < spy_sma_today
        )
        spy_crossed_above = (
            spy_close_yesterday <= spy_sma_yesterday
            and spy_close_today > spy_sma_today
        )

        if self.strategy_a_shares > 0 and spy_crossed_below:
            self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crossed_above:
            target_shares = int(
                (self.portfolio.total_portfolio_value * 0.40) // spy_close_today
            )
            if target_shares > 0:
                self.market_order(self.symbols["SPY"], target_shares)
                self.strategy_a_shares = target_shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 1:
            if self.portfolio.cash >= 20_000:
                shares = int(20_000 // float(aapl_bar.close))
                if shares > 0:
                    self.market_order(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares

