class ParallelDailyStrategiesAlgorithm(QCAlgorithm):
    SMA_PERIOD = 100
    RSI_PERIOD = 14
    AAPL_RED_DAYS_REQUIRED = 1

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi_changes = 0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_seed_gains = 0.0
        self.aapl_seed_losses = 0.0
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        spy_today_sma = None
        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))
            if len(self.spy_closes) == self.SMA_PERIOD:
                spy_today_sma = sum(self.spy_closes) / self.SMA_PERIOD

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            self._update_aapl_state(float(aapl_bar.close))

        all_bars_present = len(bars) == len(self.symbols)
        if all_bars_present:
            self._evaluate_spy(float(spy_bar.close), spy_today_sma)
            self._evaluate_aapl(float(aapl_bar.close))

        if spy_bar is not None:
            self.spy_previous_close = float(spy_bar.close)
            self.spy_previous_sma = spy_today_sma

    def _evaluate_spy(self, close, today_sma):
        if today_sma is None or self.spy_previous_sma is None:
            return

        crossed_below = (
            self.spy_previous_close >= self.spy_previous_sma
            and close < today_sma
        )
        crossed_above = (
            self.spy_previous_close <= self.spy_previous_sma
            and close > today_sma
        )

        if self.spy_lot > 0 and crossed_below:
            self.market_order(self.symbols["SPY"], -self.spy_lot, tag="Strategy A sell")
            self.spy_lot = 0

        if self.spy_lot == 0 and crossed_above:
            quantity = floor(0.40 * float(self.portfolio.total_portfolio_value) / close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity, tag="Strategy A buy")
                self.spy_lot = quantity

    def _evaluate_aapl(self, close):
        if self.aapl_rsi is None:
            return

        if self.aapl_lot > 0 and self.aapl_rsi > 60.0:
            self.market_order(self.symbols["AAPL"], -self.aapl_lot, tag="Strategy B sell")
            self.aapl_lot = 0

        if (
            self.aapl_lot == 0
            and self.aapl_red_streak >= self.AAPL_RED_DAYS_REQUIRED
            and float(self.portfolio.cash) >= 20_000.0
        ):
            quantity = floor(20_000.0 / close)
            if quantity > 0:
                self.market_order(self.symbols["AAPL"], quantity, tag="Strategy B buy")
                self.aapl_lot = quantity

    def _update_aapl_state(self, close):
        if self.aapl_previous_close is None:
            self.aapl_previous_close = close
            return

        change = close - self.aapl_previous_close
        self.aapl_red_streak = self.aapl_red_streak + 1 if change < 0 else 0
        gain = max(change, 0.0)
        loss = max(-change, 0.0)
        self.aapl_rsi_changes += 1

        if self.aapl_rsi_changes <= self.RSI_PERIOD:
            self.aapl_seed_gains += gain
            self.aapl_seed_losses += loss
            if self.aapl_rsi_changes == self.RSI_PERIOD:
                self.aapl_average_gain = self.aapl_seed_gains / self.RSI_PERIOD
                self.aapl_average_loss = self.aapl_seed_losses / self.RSI_PERIOD
                self.aapl_rsi = self._rsi_value()
        else:
            self.aapl_average_gain = (
                self.aapl_average_gain * (self.RSI_PERIOD - 1) + gain
            ) / self.RSI_PERIOD
            self.aapl_average_loss = (
                self.aapl_average_loss * (self.RSI_PERIOD - 1) + loss
            ) / self.RSI_PERIOD
            self.aapl_rsi = self._rsi_value()

        self.aapl_previous_close = close

    def _rsi_value(self):
        if self.aapl_average_loss == 0.0:
            return 100.0 if self.aapl_average_gain > 0.0 else 50.0
        relative_strength = self.aapl_average_gain / self.aapl_average_loss
        return 100.0 - 100.0 / (1.0 + relative_strength)

