class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, privately accounted daily equity strategies."""

    AAPL_RED_DAYS_REQUIRED = 3

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}

        # This supplies pre-start observations while leaving all rule evaluation
        # disabled until the configured backtest begins and both indicators are ready.
        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        bars = data.bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Market-state quantities continue to consume their own available data even
        # when a missing bar requires the day's complete rule evaluation to be skipped.
        if spy in bars:
            spy_close = bars[spy].close
            self.spy_sma.update(data.time, spy_close)
        else:
            spy_close = None

        if aapl in bars:
            aapl_close = bars[aapl].close
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(data.time, aapl_close)
        else:
            aapl_close = None

        all_bars_present = all(
            symbol in bars for symbol in self.symbols.values()
        )

        if (
            all_bars_present
            and not self.is_warming_up
            and self.spy_sma.is_ready
            and self.aapl_rsi.is_ready
        ):
            # Both independent slots evaluate their sell side before their buy side.
            self._evaluate_spy(spy_close)
            self._evaluate_aapl(aapl_close)

        if spy_close is not None:
            self.previous_spy_close = spy_close
            if self.spy_sma.is_ready:
                self.previous_spy_sma = self.spy_sma.current.value
        if aapl_close is not None:
            self.previous_aapl_close = aapl_close

    def _evaluate_spy(self, close):
        symbol = self.symbols["SPY"]
        if symbol in self.pending_orders:
            return

        sma = self.spy_sma.current.value
        crosses_below = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and close < sma
        )
        crosses_above = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and close > sma
        )

        if self.spy_lot > 0:
            if crosses_below:
                self._submit_lot_order(symbol, -self.spy_lot, "Strategy A sell")
            return

        if crosses_above:
            quantity = self.calculate_order_quantity(symbol, 0.40)
            if quantity > 0:
                self._submit_lot_order(symbol, quantity, "Strategy A buy")

    def _evaluate_aapl(self, close):
        symbol = self.symbols["AAPL"]
        if symbol in self.pending_orders:
            return

        if self.aapl_lot > 0:
            if self.aapl_rsi.current.value > 60:
                self._submit_lot_order(symbol, -self.aapl_lot, "Strategy B sell")
            return

        if self.aapl_red_streak >= self.AAPL_RED_DAYS_REQUIRED:
            cash_required = 20_000
            if self.portfolio.cash >= cash_required:
                quantity = int(cash_required // close)
                if quantity > 0:
                    self._submit_lot_order(symbol, quantity, "Strategy B buy")

    def _submit_lot_order(self, symbol, quantity, tag):
        self.pending_orders[symbol] = None
        ticket = self.market_order(symbol, quantity, tag=tag)
        if ticket.status in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID,
        ):
            self.pending_orders.pop(symbol, None)
        else:
            self.pending_orders[symbol] = ticket.order_id

    def on_order_event(self, order_event: OrderEvent):
        symbol = order_event.symbol
        if symbol not in (self.symbols["SPY"], self.symbols["AAPL"]):
            return

        if order_event.status in (OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED):
            if symbol == self.symbols["SPY"]:
                self.spy_lot += order_event.fill_quantity
            else:
                self.aapl_lot += order_event.fill_quantity

        if order_event.status in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID,
        ):
            self.pending_orders.pop(symbol, None)

