class IndependentSpyAaplStrategies(QCAlgorithm):
    RED_DAYS_REQUIRED = 3

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.symbols["SPY"], 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_closes = {}
        self.previous_spy_spread = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(aapl):
            aapl_close = data.Bars[aapl].Close
            if aapl in self.previous_closes:
                if aapl_close < self.previous_closes[aapl]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_closes[aapl] = aapl_close

        has_every_bar = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if has_every_bar and self.spy_sma.IsReady and self.aapl_rsi.IsReady:
            spy_close = data.Bars[spy].Close
            spy_spread = spy_close - self.spy_sma.Current.Value

            if self.spy_lot > 0 and not self.spy_order_pending:
                if self.previous_spy_spread is not None:
                    crossed_below = (
                        self.previous_spy_spread >= 0 and spy_spread < 0
                    )
                    if crossed_below:
                        self.spy_order_pending = True
                        self.MarketOrder(spy, -self.spy_lot, tag="Strategy A sell")

            if (
                self.spy_lot == 0
                and not self.spy_order_pending
                and self.previous_spy_spread is not None
            ):
                crossed_above = self.previous_spy_spread <= 0 and spy_spread > 0
                if crossed_above:
                    quantity = self.CalculateOrderQuantity(spy, 0.40)
                    if quantity > 0:
                        self.spy_order_pending = True
                        self.MarketOrder(spy, quantity, tag="Strategy A buy")

            if self.aapl_lot > 0 and not self.aapl_order_pending:
                if self.aapl_rsi.Current.Value > 60:
                    self.aapl_order_pending = True
                    self.MarketOrder(
                        aapl, -self.aapl_lot, tag="Strategy B sell"
                    )

            if self.aapl_lot == 0 and not self.aapl_order_pending:
                if self.aapl_red_streak >= self.RED_DAYS_REQUIRED:
                    cash_to_invest = 20_000
                    if self.Portfolio.Cash >= cash_to_invest:
                        quantity = floor(cash_to_invest / data.Bars[aapl].Close)
                        if quantity > 0:
                            self.aapl_order_pending = True
                            self.MarketOrder(
                                aapl, quantity, tag="Strategy B buy"
                            )

        if data.Bars.ContainsKey(spy) and self.spy_sma.IsReady:
            self.previous_spy_spread = (
                data.Bars[spy].Close - self.spy_sma.Current.Value
            )
        if data.Bars.ContainsKey(spy):
            self.previous_closes[spy] = data.Bars[spy].Close

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            return

        if order_event.Symbol == self.symbols["SPY"]:
            self.spy_lot += int(order_event.FillQuantity)
            if order_event.Status == OrderStatus.Filled:
                self.spy_order_pending = False
        elif order_event.Symbol == self.symbols["AAPL"]:
            self.aapl_lot += int(order_event.FillQuantity)
            if order_event.Status == OrderStatus.Filled:
                self.aapl_order_pending = False

