                ticker, Resolution.Daily
            ).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.consecutive_red_days = 3

    def OnData(self, data: Slice):
        bars = data.Bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Market-state quantities continue to consume each ticker's data even
        # when another subscription is absent from the slice.
        if bars.ContainsKey(spy):
            spy_bar = bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        if bars.ContainsKey(aapl):
            aapl_bar = bars[aapl]
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(
            bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if all_bars_present:
            spy_bar = bars[spy]
            aapl_bar = bars[aapl]

            spy_invested = self.Portfolio[spy].Quantity != 0
            aapl_invested = self.Portfolio[aapl].Quantity != 0

            # All sells are evaluated before either independent strategy buys.
            if (
                spy_invested
                and self.spy_sma.IsReady
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close >= self.previous_spy_sma
                and spy_bar.Close < self.spy_sma.Current.Value
            ):
                self.MarketOrder(spy, -self.Portfolio[spy].Quantity)

            if (
                aapl_invested
                and self.aapl_rsi.IsReady
                and self.aapl_rsi.Current.Value > 60
            ):
                self.MarketOrder(aapl, -self.Portfolio[aapl].Quantity)

            if (
                not spy_invested
                and self.spy_sma.IsReady
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close <= self.previous_spy_sma
                and spy_bar.Close > self.spy_sma.Current.Value
            ):
                quantity = int(
                    (self.Portfolio.TotalPortfolioValue * 0.40)
                    // spy_bar.Close
                )
                if quantity > 0:
                    self.MarketOrder(spy, quantity)

            if (
                not aapl_invested
                and self.previous_aapl_close is not None
                and self.aapl_red_streak >= self.consecutive_red_days
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = int(20_000 // aapl_bar.Close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)

        if bars.ContainsKey(spy) and self.spy_sma.IsReady:
            self.previous_spy_close = bars[spy].Close
            self.previous_spy_sma = self.spy_sma.Current.Value
        if bars.ContainsKey(aapl):
            self.previous_aapl_close = bars[aapl].Close

