class IndependentSpyAaplStrategies(QCAlgorithm):
    RED_DAYS_REQUIRED = 3

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities are updated whenever their own bar is present,
        # even when a missing bar elsewhere prevents rule evaluation.
        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].Close))

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if len(bars) != len(self.symbols):
            return

        # Both strategies are independent.  Each strategy evaluates its sell
        # before its buy, and an outstanding order keeps that lot unavailable.
        self._evaluate_spy(bars["SPY"])
        self._evaluate_aapl(bars["AAPL"])

    def _evaluate_spy(self, bar):
        symbol = self.symbols["SPY"]
        if symbol in self.pending_orders or len(self.spy_closes) < 101:
            return

        closes = list(self.spy_closes)
        yesterday_close = closes[-2]
        today_close = closes[-1]
        yesterday_sma = sum(closes[-101:-1]) / 100.0
        today_sma = sum(closes[-100:]) / 100.0

        crosses_below = yesterday_close >= yesterday_sma and today_close < today_sma
        crosses_above = yesterday_close <= yesterday_sma and today_close > today_sma

        if self.spy_lot > 0:
            if crosses_below:
                ticket = self.MarketOrder(symbol, -self.spy_lot)
                self.pending_orders[symbol] = ticket.OrderId
            return

        if crosses_above:
            quantity = floor(float(self.Portfolio.TotalPortfolioValue) * 0.40 / float(bar.Close))
            if quantity > 0:
                ticket = self.MarketOrder(symbol, quantity)
                self.pending_orders[symbol] = ticket.OrderId

    def _evaluate_aapl(self, bar):
        symbol = self.symbols["AAPL"]
        if symbol in self.pending_orders or not self.aapl_rsi.IsReady:
            return

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.Current.Value) > 60.0:
                ticket = self.MarketOrder(symbol, -self.aapl_lot)
                self.pending_orders[symbol] = ticket.OrderId
            return

        if self.aapl_red_streak >= self.RED_DAYS_REQUIRED:
            allocation = 20_000.0
            if float(self.Portfolio.Cash) >= allocation:
                quantity = floor(allocation / float(bar.Close))
                if quantity > 0:
                    ticket = self.MarketOrder(symbol, quantity)
                    self.pending_orders[symbol] = ticket.OrderId

    def OnOrderEvent(self, order_event: OrderEvent):
        symbol = order_event.Symbol
        if order_event.Status in (OrderStatus.Invalid, OrderStatus.Canceled):
            self.pending_orders.pop(symbol, None)
            return

        if order_event.Status not in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            return

        fill_quantity = int(order_event.FillQuantity)
        if symbol == self.symbols["SPY"]:
            self.spy_lot += fill_quantity
        elif symbol == self.symbols["AAPL"]:
            self.aapl_lot += fill_quantity

        if order_event.Status == OrderStatus.Filled:
            self.pending_orders.pop(symbol, None)
            if symbol == self.symbols["SPY"]:
                self.spy_lot = max(0, self.spy_lot)
            elif symbol == self.symbols["AAPL"]:
                self.aapl_lot = max(0, self.aapl_lot)

