class IndependentSpyAaplStrategies(QCAlgorithm):
    RED_DAYS_REQUIRED = 3

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in self.tickers
        }

        self.spy_closes = deque(maxlen=100)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.rsi_previous_close = None
        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}
        for ticker in self.tickers:
            symbol = self.symbols[ticker]
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_crosses_above, spy_crosses_below = self._update_spy(bars.get("SPY"))
        self._update_aapl(bars.get("AAPL"))

        if len(bars) != len(self.tickers):
            return

        spy_close = bars["SPY"].Close
        aapl_close = bars["AAPL"].Close

        # Sells are evaluated before either independent strategy's buy.
        if self.spy_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi is not None and self.aapl_rsi > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crosses_above:
            target_value = self.Portfolio.TotalPortfolioValue * 0.40
            quantity = math.floor(target_value / spy_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= self.RED_DAYS_REQUIRED:
            if self.Portfolio.Cash >= 20_000:
                quantity = math.floor(20_000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

    def _update_spy(self, bar):
        if bar is None:
            return False, False

        close = bar.Close
        self.spy_closes.append(close)
        current_sma = None
        if len(self.spy_closes) == self.spy_closes.maxlen:
            current_sma = sum(self.spy_closes) / len(self.spy_closes)

        crosses_above = False
        crosses_below = False
        if (
            current_sma is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close is not None
        ):
            crosses_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and close > current_sma
            )
            crosses_below = (
                self.previous_spy_close >= self.previous_spy_sma
                and close < current_sma
            )

        self.previous_spy_close = close
        self.previous_spy_sma = current_sma
        return crosses_above, crosses_below

    def _update_aapl(self, bar):
        if bar is None:
            return

        close = bar.Close
        if self.previous_aapl_close is not None:
            if close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if self.rsi_previous_close is not None:
            change = close - self.rsi_previous_close
            gain = max(change, 0)
            loss = max(-change, 0)

            if self.rsi_average_gain is None:
                self.rsi_seed_gains.append(gain)
                self.rsi_seed_losses.append(loss)
                if len(self.rsi_seed_gains) == 14:
                    self.rsi_average_gain = sum(self.rsi_seed_gains) / 14
                    self.rsi_average_loss = sum(self.rsi_seed_losses) / 14
            else:
                self.rsi_average_gain = (self.rsi_average_gain * 13 + gain) / 14
                self.rsi_average_loss = (self.rsi_average_loss * 13 + loss) / 14

            if self.rsi_average_gain is not None:
                if self.rsi_average_loss == 0:
                    self.aapl_rsi = 100.0
                else:
                    relative_strength = self.rsi_average_gain / self.rsi_average_loss
                    self.aapl_rsi = 100 - 100 / (1 + relative_strength)

        self.previous_aapl_close = close
        self.rsi_previous_close = close

