class IndependentDailyStrategies(QCAlgorithm):
    RED_DAYS_REQUIRED = 1

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            security = self.AddEquity(ticker, Resolution.Daily)
            security.SetDataNormalizationMode(DataNormalizationMode.Adjusted)
            self.symbols[ticker] = security.Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        self._apply_splits(data)

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_symbols_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if all_symbols_present:
            spy_bar = data.Bars[spy]
            aapl_bar = data.Bars[aapl]

            if self.spy_lot > 0 and self._spy_crosses_below(spy_bar.Close):
                self.MarketOrder(spy, -self.spy_lot, tag="Strategy A: close lot")
                self.spy_lot = 0

            if self.aapl_lot > 0 and self.aapl_rsi.IsReady:
                if self.aapl_rsi.Current.Value > 60:
                    self.MarketOrder(aapl, -self.aapl_lot, tag="Strategy B: close lot")
                    self.aapl_lot = 0

            if self.spy_lot == 0 and self._spy_crosses_above(spy_bar.Close):
                shares = int(
                    (self.Portfolio.TotalPortfolioValue * Decimal("0.40"))
                    // spy_bar.Close
                )
                if shares > 0:
                    self.MarketOrder(spy, shares, tag="Strategy A: open lot")
                    self.spy_lot = shares

            if (
                self.aapl_lot == 0
                and self.aapl_rsi.IsReady
                and self.aapl_red_streak >= self.RED_DAYS_REQUIRED
                and self.Portfolio.Cash >= 20_000
            ):
                shares = int(Decimal("20000") // aapl_bar.Close)
                if shares > 0:
                    self.MarketOrder(aapl, shares, tag="Strategy B: open lot")
                    self.aapl_lot = shares

        if data.Bars.ContainsKey(spy) and self.spy_sma.IsReady:
            self.previous_spy_close = data.Bars[spy].Close
            self.previous_spy_sma = self.spy_sma.Current.Value

        if data.Bars.ContainsKey(aapl):
            self.previous_aapl_close = data.Bars[aapl].Close

    def _spy_crosses_above(self, close):
        return (
            self.spy_sma.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and close > self.spy_sma.Current.Value
        )

    def _spy_crosses_below(self, close):
        return (
            self.spy_sma.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and close < self.spy_sma.Current.Value
        )

    def _apply_splits(self, data):
        for split in data.Splits.Values:
            if split.Type != SplitType.SplitOccurred or split.SplitFactor == 0:
                continue
            if split.Symbol == self.symbols["SPY"] and self.spy_lot > 0:
                self.spy_lot = int(self.spy_lot / split.SplitFactor)
            elif split.Symbol == self.symbols["AAPL"] and self.aapl_lot > 0:
                self.aapl_lot = int(self.aapl_lot / split.SplitFactor)

