        self.spy_sma = self.sma(
            self.symbols["SPY"], 100, Resolution.DAILY
        )
        self.aapl_rsi = self.rsi(
            self.symbols["AAPL"], 14, MovingAverageType.WILDERS,
            Resolution.DAILY
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order = None
        self.aapl_order = None

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        if not all(data.Bars.ContainsKey(symbol)
                   for symbol in self.symbols.values()):
            return

        spy_bar = data.Bars[self.symbols["SPY"]]
        aapl_bar = data.Bars[self.symbols["AAPL"]]

        if self.previous_aapl_close is not None:
            if aapl_bar.close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        spy_sma_ready = self.spy_sma.is_ready
        current_spy_sma = self.spy_sma.current.value if spy_sma_ready else None

        if self.spy_order is None and spy_sma_ready \
                and self.previous_spy_sma is not None:
            crosses_below = (
                self.previous_spy_close >= self.previous_spy_sma
                and spy_bar.close < current_spy_sma
            )
            crosses_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_bar.close > current_spy_sma
            )

            if self.spy_lot > 0 and crosses_below:
                self.spy_order = self.market_order(
                    self.symbols["SPY"], -self.spy_lot
                )
            elif self.spy_lot == 0 and crosses_above:
                quantity = floor(
                    0.40 * self.portfolio.total_portfolio_value
                    / spy_bar.close
                )
                if quantity > 0:
                    self.spy_order = self.market_order(
                        self.symbols["SPY"], quantity
                    )

        if self.aapl_order is None and self.aapl_rsi.is_ready:
            if self.aapl_lot > 0 and self.aapl_rsi.current.value > 60:
                self.aapl_order = self.market_order(
                    self.symbols["AAPL"], -self.aapl_lot
                )
            elif (self.aapl_lot == 0
                  and self.aapl_red_streak >= self.RED_DAYS_REQUIRED
                  and self.portfolio.cash >= 20_000):
                quantity = floor(20_000 / aapl_bar.close)
                if quantity > 0:
                    self.aapl_order = self.market_order(
                        self.symbols["AAPL"], quantity
                    )

        self.previous_spy_close = spy_bar.close
        if spy_sma_ready:
            self.previous_spy_sma = current_spy_sma
        self.previous_aapl_close = aapl_bar.close

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
            if order_event.symbol == self.symbols["SPY"]:
                self.spy_order = None
            elif order_event.symbol == self.symbols["AAPL"]:
                self.aapl_order = None
            return

        if order_event.status not in (OrderStatus.FILLED,
                                      OrderStatus.PARTIALLY_FILLED):
            return

        if order_event.symbol == self.symbols["SPY"]:
            self.spy_lot += order_event.fill_quantity
            if order_event.status == OrderStatus.FILLED:
                self.spy_order = None
        elif order_event.symbol == self.symbols["AAPL"]:
            self.aapl_lot += order_event.fill_quantity
            if order_event.status == OrderStatus.FILLED:
                self.aapl_order = None

