class IndependentSpyAaplStrategies(QCAlgorithm):
    RED_DAYS_REQUIRED = 3

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        spy = bars.get("SPY")
        aapl = bars.get("AAPL")

        old_aapl_close = self.previous_aapl_close

        if spy is not None:
            self.spy_sma.update(spy.end_time, spy.close)

        if aapl is not None:
            self.aapl_rsi.update(aapl.end_time, aapl.close)
            if old_aapl_close is None or aapl.close == old_aapl_close:
                self.aapl_red_streak = 0
            elif aapl.close < old_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = aapl.close

        if len(bars) != len(self.symbols):
            if spy is not None:
                self.previous_spy_close = spy.close
                self.previous_spy_sma = (
                    self.spy_sma.current.value if self.spy_sma.is_ready else None
                )
            return

        spy_sma = self.spy_sma.current.value
        spy_crosses_below = (
            self.spy_lot > 0
            and "SPY" not in self.pending_orders
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and spy.close < spy_sma
        )
        if spy_crosses_below:
            self._place_lot_order("SPY", -self.spy_lot)

        if (
            self.aapl_lot > 0
            and "AAPL" not in self.pending_orders
            and self.aapl_rsi.is_ready
            and self.aapl_rsi.current.value > 60
        ):
            self._place_lot_order("AAPL", -self.aapl_lot)

        spy_crosses_above = (
            self.spy_lot == 0
            and "SPY" not in self.pending_orders
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and spy.close > spy_sma
        )
        if spy_crosses_above:
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self._place_lot_order("SPY", quantity)

        if (
            self.aapl_lot == 0
            and "AAPL" not in self.pending_orders
            and self.aapl_rsi.is_ready
            and self.aapl_red_streak >= self.RED_DAYS_REQUIRED
            and self.portfolio.cash >= 20_000
        ):
            quantity = floor(20_000 / aapl.close)
            if quantity > 0:
                self._place_lot_order("AAPL", quantity)

        self.previous_spy_close = spy.close
        self.previous_spy_sma = spy_sma

    def _place_lot_order(self, ticker, quantity):
        ticket = self.market_order(
            self.symbols[ticker], quantity, tag=f"{ticker} private strategy lot"
        )
        self.pending_orders[ticker] = ticket.order_id

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in (OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED):
            if order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                for ticker, order_id in list(self.pending_orders.items()):
                    if order_id == order_event.order_id:
                        del self.pending_orders[ticker]
            return

        for ticker, order_id in list(self.pending_orders.items()):
            if order_id != order_event.order_id:
                continue
            if ticker == "SPY":
                self.spy_lot += order_event.fill_quantity
            else:
                self.aapl_lot += order_event.fill_quantity
            if order_event.status == OrderStatus.FILLED:
                del self.pending_orders[ticker]
            break

