class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # 101 closes are retained so both today's and yesterday's 100-day
        # moving averages can be evaluated using their respective day values.
        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        # Market-state quantities continue to consume every available bar even
        # when another subscription is absent and trading rules must be skipped.
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.Add(float(data.Bars[self.spy].Close))

        if data.Bars.ContainsKey(self.aapl):
            aapl_close = float(data.Bars[self.aapl].Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(data.Bars[self.aapl].EndTime, aapl_close)

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        # All sell rules are evaluated before any buy rule.
        self._evaluate_spy_sell()
        self._evaluate_aapl_sell()
        self._evaluate_spy_buy()
        self._evaluate_aapl_buy()

    def _spy_cross_values(self):
        if not self.spy_closes.IsReady:
            return None

        today_close = self.spy_closes[0]
        yesterday_close = self.spy_closes[1]
        today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        return yesterday_close, yesterday_sma, today_close, today_sma

    def _evaluate_spy_sell(self):
        if self.spy_lot == 0:
            return
        values = self._spy_cross_values()
        if values is None:
            return
        yesterday_close, yesterday_sma, today_close, today_sma = values
        if yesterday_close >= yesterday_sma and today_close < today_sma:
            self.MarketOrder(self.spy, -self.spy_lot)
            self.spy_lot = 0

    def _evaluate_aapl_sell(self):
        if self.aapl_lot == 0 or not self.aapl_rsi.IsReady:
            return
        if self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.aapl_lot)
            self.aapl_lot = 0

    def _evaluate_spy_buy(self):
        if self.spy_lot != 0:
            return
        values = self._spy_cross_values()
        if values is None:
            return
        yesterday_close, yesterday_sma, today_close, today_sma = values
        if yesterday_close <= yesterday_sma and today_close > today_sma:
            quantity = self.CalculateOrderQuantity(self.spy, 0.40)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.spy_lot = quantity

    def _evaluate_aapl_buy(self):
        if self.aapl_lot != 0 or not self.aapl_rsi.IsReady:
            return
        # "A number" supplies no larger threshold, so a completed positive
        # run is the exact satisfiable condition: one or more consecutive reds.
        if self.aapl_red_streak >= 1 and self.Portfolio.Cash >= 20_000:
            close = float(self.Securities[self.aapl].Close)
            quantity = int(20_000 // close)
            if quantity > 0:
                self.MarketOrder(self.aapl, quantity)
                self.aapl_lot = quantity

